   138→    /// <summary>
   139→    /// Processed block validation is comparing the block hashes (which include all other results).
   140→    /// We only make exact checks on what is invalid if the hash is different.
   141→    /// </summary>
   142→    /// <param name="processedBlock">This should be the block processing result (after going through the EVM processing)</param>
   143→    /// <param name="receipts">List of tx receipts from the processed block (required only for better diagnostics when the receipt root is invalid).</param>
   144→    /// <param name="suggestedBlock">Block received from the network - unchanged.</param>
   145→    /// <returns><c>true</c> if the <paramref name="processedBlock"/> is valid; otherwise, <c>false</c>.</returns>
   146→    public bool ValidateProcessedBlock(Block processedBlock, TxReceipt[] receipts, Block suggestedBlock) =>
   147→        ValidateProcessedBlock(processedBlock, receipts, suggestedBlock, out _);
   148→
   149→    /// <summary>
   150→    /// Processed block validation is comparing the block hashes (which include all other results).
   151→    /// We only make exact checks on what is invalid if the hash is different.
   152→    /// </summary>
   153→    /// <param name="processedBlock">This should be the block processing result (after going through the EVM processing)</param>
   154→    /// <param name="receipts">List of tx receipts from the processed block (required only for better diagnostics when the receipt root is invalid).</param>
   155→    /// <param name="suggestedBlock">Block received from the network - unchanged.</param>
   156→    /// <param name="error">Detailed error message if validation fails otherwise <value>null</value>.</param>
   157→    /// <returns><c>true</c> if the <paramref name="processedBlock"/> is valid; otherwise, <c>false</c>.</returns>
   158→    public bool ValidateProcessedBlock(Block processedBlock, TxReceipt[] receipts, Block suggestedBlock, out string? error)
   159→    {
   160→        if (processedBlock.Header.Hash == suggestedBlock.Header.Hash)
   161→        {
   162→            error = null;
   163→            return true;
   164→        }
   165→
   166→        if (_logger.IsWarn) _logger.Warn($"Processed block {processedBlock.ToString(Block.Format.Short)} is invalid:");
   167→        if (_logger.IsWarn) _logger.Warn($"- hash: expected {suggestedBlock.Hash}, got {processedBlock.Hash}");
   168→        error = null;
   169→        if (processedBlock.Header.GasUsed != suggestedBlock.Header.GasUsed)
   170→        {
   171→            if (_logger.IsWarn) _logger.Warn($"- gas used: expected {suggestedBlock.Header.GasUsed}, got {processedBlock.Header.GasUsed} (diff: {processedBlock.Header.GasUsed - suggestedBlock.Header.GasUsed})");
   172→            error ??= BlockErrorMessages.HeaderGasUsedMismatch(suggestedBlock.Header.GasUsed, processedBlock.Header.GasUsed);
   173→        }
   174→
   175→        if (processedBlock.Header.Bloom != suggestedBlock.Header.Bloom)
   176→        {
   177→            if (_logger.IsWarn) _logger.Warn($"- bloom: expected {suggestedBlock.Header.Bloom}, got {processedBlock.Header.Bloom}");
   178→            error ??= BlockErrorMessages.InvalidLogsBloom(suggestedBlock.Header.Bloom, processedBlock.Header.Bloom);
   179→        }
   180→
   181→        if (processedBlock.Header.ReceiptsRoot != suggestedBlock.Header.ReceiptsRoot)
   182→        {
   183→            if (_logger.IsWarn) _logger.Warn($"- receipts root: expected {suggestedBlock.Header.ReceiptsRoot}, got {processedBlock.Header.ReceiptsRoot}");
   184→            error ??= BlockErrorMessages.InvalidReceiptsRoot(suggestedBlock.Header.ReceiptsRoot, processedBlock.Header.ReceiptsRoot);
   185→        }
   186→
   187→        if (processedBlock.Header.StateRoot != suggestedBlock.Header.StateRoot)
   188→        {
   189→            if (_logger.IsWarn) _logger.Warn($"- state root: expected {suggestedBlock.Header.StateRoot}, got {processedBlock.Header.StateRoot}");
   190→            error ??= BlockErrorMessages.InvalidStateRoot(suggestedBlock.Header.StateRoot, processedBlock.Header.StateRoot);
   191→        }
   192→
   193→        if (processedBlock.Header.BlobGasUsed != suggestedBlock.Header.BlobGasUsed)
   194→        {
   195→            if (_logger.IsWarn) _logger.Warn($"- blob gas used: expected {suggestedBlock.Header.BlobGasUsed}, got {processedBlock.Header.BlobGasUsed}");
   196→            error ??= BlockErrorMessages.HeaderBlobGasMismatch(suggestedBlock.Header.BlobGasUsed, processedBlock.Header.BlobGasUsed);
   197→        }
   198→
   199→        if (processedBlock.Header.ExcessBlobGas != suggestedBlock.Header.ExcessBlobGas)
   200→        {
   201→            if (_logger.IsWarn) _logger.Warn($"- excess blob gas: expected {suggestedBlock.Header.ExcessBlobGas}, got {processedBlock.Header.ExcessBlobGas}");
   202→            error ??= BlockErrorMessages.IncorrectExcessBlobGas(suggestedBlock.Header.ExcessBlobGas, processedBlock.Header.ExcessBlobGas);
   203→        }
   204→
   205→        if (processedBlock.Header.ParentBeaconBlockRoot != suggestedBlock.Header.ParentBeaconBlockRoot)
   206→        {
   207→            if (_logger.IsWarn) _logger.Warn($"- parent beacon block root : expected {suggestedBlock.Header.ParentBeaconBlockRoot}, got {processedBlock.Header.ParentBeaconBlockRoot}");
   208→            error ??= BlockErrorMessages.InvalidParentBeaconBlockRoot(suggestedBlock.Header.ParentBeaconBlockRoot, processedBlock.Header.ParentBeaconBlockRoot);
   209→        }
   210→
   211→        if (processedBlock.Header.RequestsHash != suggestedBlock.Header.RequestsHash)
   212→        {
   213→            if (_logger.IsWarn) _logger.Warn($"- requests root : expected {suggestedBlock.Header.RequestsHash}, got {processedBlock.Header.RequestsHash}");
   214→            error ??= BlockErrorMessages.InvalidRequestsHash(suggestedBlock.Header.RequestsHash, processedBlock.Header.RequestsHash);
   215→        }
   216→
   217→        for (int i = 0; i < processedBlock.Transactions.Length; i++)
   218→        {
   219→            if (receipts[i].Error is not null && receipts[i].GasUsed == 0 && receipts[i].Error == "invalid")
   220→            {
   221→                if (_logger.IsWarn) _logger.Warn($"- invalid transaction {i}");
   222→                error ??= BlockErrorMessages.InvalidTxInBlock(i);
   223→            }
   224→        }
   225→
   226→        if (suggestedBlock.ExtraData is not null)
   227→        {
   228→            if (_logger.IsWarn) _logger.Warn($"- block extra data : {suggestedBlock.ExtraData.ToHexString()}, UTF8: {Encoding.UTF8.GetString(suggestedBlock.ExtraData)}");
   229→        }
   230→
   231→        return false;
   232→    }
   233→
   234→    public bool ValidateWithdrawals(Block block, out string? error) =>
   235→        ValidateWithdrawals(block, _specProvider.GetSpec(block.Header), out error);
   236→
   237→    protected virtual bool ValidateWithdrawals(Block block, IReleaseSpec spec, out string? error)
   238→    {
   239→        if (spec.WithdrawalsEnabled && block.Withdrawals is null)
   240→        {
   241→            error = BlockErrorMessages.MissingWithdrawals;
   242→
   243→            if (_logger.IsWarn) _logger.Warn($"Withdrawals cannot be null in block {block.Hash} when EIP-4895 activated.");
   244→
   245→            return false;
   246→        }
   247→
   248→        if (!spec.WithdrawalsEnabled && block.Withdrawals is not null)
   249→        {
   250→            error = BlockErrorMessages.WithdrawalsNotEnabled;
   251→
   252→            if (_logger.IsWarn) _logger.Warn($"Withdrawals must be null in block {block.Hash} when EIP-4895 not activated.");
   253→
   254→            return false;
   255→        }
   256→
   257→        if (block.Withdrawals is not null)
   258→        {
   259→            if (!ValidateWithdrawalsHashMatches(block, out Hash256 withdrawalsRoot))
   260→            {
   261→                error = BlockErrorMessages.InvalidWithdrawalsRoot(block.Header.WithdrawalsRoot, withdrawalsRoot);
   262→                if (_logger.IsWarn) _logger.Warn($"Withdrawals root hash mismatch in block {block.ToString(Block.Format.FullHashAndNumber)}: expected {block.Header.WithdrawalsRoot}, got {withdrawalsRoot}");
   263→
   264→                return false;
   265→            }
   266→        }
   267→
   268→        error = null;
   269→
   270→        return true;
   271→    }
   272→
   273→    protected virtual bool ValidateTransactions(Block block, IReleaseSpec spec, out string? errorMessage)
   274→    {
   275→        Transaction[] transactions = block.Transactions;
   276→
   277→        for (int txIndex = 0; txIndex < transactions.Length; txIndex++)
   278→        {
   279→            Transaction transaction = transactions[txIndex];
   280→
   281→            ValidationResult isWellFormed = _txValidator.IsWellFormed(transaction, spec);
   282→            if (!isWellFormed)
   283→            {
   284→                if (_logger.IsDebug) _logger.Debug($"{Invalid(block)} Invalid transaction: {isWellFormed}");
   285→                errorMessage = isWellFormed.Error;
   286→                return false;
   287→            }
   288→        }
   289→        errorMessage = null;
   290→        return true;
   291→    }
   292→
   293→    protected virtual bool ValidateEip4844Fields(Block block, IReleaseSpec spec, out string? error)
   294→    {
   295→        if (!spec.IsEip4844Enabled)
   296→        {
   297→            error = null;
   298→            return true;
   299→        }
   300→
   301→        int blobsInBlock = 0;
   302→        UInt256 feePerBlobGas = UInt256.Zero;
   303→        Transaction[] transactions = block.Transactions;
   304→
   305→        for (int txIndex = 0; txIndex < transactions.Length; txIndex++)
   306→        {
   307→            Transaction transaction = transactions[txIndex];
   308→
   309→            if (!transaction.SupportsBlobs)
   310→            {
   311→                continue;
   312→            }
   313→
   314→            if (feePerBlobGas.IsZero)
   315→            {
   316→                if (!BlobGasCalculator.TryCalculateFeePerBlobGas(block.Header, spec.BlobBaseFeeUpdateFraction, out feePerBlobGas))
   317→                {
   318→                    error = BlockErrorMessages.BlobGasPriceOverflow;
   319→                    if (_logger.IsDebug) _logger.Debug($"{Invalid(block)} {error}.");
   320→                    return false;
   321→                }
   322→            }
   323→
   324→            if (transaction.MaxFeePerBlobGas < feePerBlobGas)
   325→            {
   326→                error = BlockErrorMessages.InsufficientMaxFeePerBlobGas;
   327→                if (_logger.IsDebug) _logger.Debug($"{Invalid(block)} Transaction at index {txIndex} has insufficient {nameof(transaction.MaxFeePerBlobGas)} to cover current blob gas fee: {transaction.MaxFeePerBlobGas} < {feePerBlobGas}.");
   328→                return false;
   329→            }
   330→
   331→            blobsInBlock += transaction.BlobVersionedHashes!.Length;
   332→        }
   333→
   334→        ulong blobGasUsed = BlobGasCalculator.CalculateBlobGas(blobsInBlock);
   335→
   336→        if (blobGasUsed > spec.GetMaxBlobGasPerBlock())
   337→        {
   338→            error = BlockErrorMessages.BlobGasUsedAboveBlockLimit(spec.GetMaxBlobGasPerBlock(), blobsInBlock, blobGasUsed);
   339→            if (_logger.IsDebug) _logger.Debug($"{Invalid(block)} {error}.");
   340→            return false;
   341→        }
   342→
   343→        if (blobGasUsed != block.Header.BlobGasUsed)
   344→        {
   345→            error = BlockErrorMessages.HeaderBlobGasMismatch(blobGasUsed, block.Header.BlobGasUsed);
   346→            if (_logger.IsDebug) _logger.Debug($"{Invalid(block)} {nameof(BlockHeader.BlobGasUsed)} declared in the block header does not match actual blob gas used: {block.Header.BlobGasUsed} != {blobGasUsed}.");
   347→            return false;
   348→        }
   349→
   350→        error = null;
   351→        return true;
   352→    }
   353→
   354→    public bool ValidateBodyAgainstHeader(BlockHeader header, BlockBody toBeValidated) =>
   355→        ValidateBodyAgainstHeader(header, toBeValidated, out _);
   356→
   357→    public virtual bool ValidateBodyAgainstHeader(BlockHeader header, BlockBody toBeValidated, out string? errorMessage)
   358→    {
   359→        if (!ValidateTxRootMatchesTxs(header, toBeValidated, out Hash256? txRoot))
   360→        {
   361→            errorMessage = BlockErrorMessages.InvalidTxRoot(header.TxRoot, txRoot);
   362→            return false;
   363→        }
   364→
   365→        if (!ValidateUnclesHashMatches(header, toBeValidated, out _))
   366→        {
   367→            errorMessage = BlockErrorMessages.InvalidUnclesHash;
   368→            return false;
   369→        }
   370→
   371→        if (!ValidateWithdrawalsHashMatches(header, toBeValidated, out Hash256? withdrawalsRoot))
   372→        {
   373→            errorMessage = BlockErrorMessages.InvalidWithdrawalsRoot(header.WithdrawalsRoot, withdrawalsRoot);
   374→            return false;
   375→        }
   376→
   377→        errorMessage = null;
   378→        return true;
   379→    }
